python3 - <<'EOF'
import os, re
root='/challenge/inhere'
pat=re.compile(rb'^record \d\d-\d\d$')
for dp,_,fns in os.walk(root):
    for fn in fns:
        p=os.path.join(dp,fn)
        data=open(p,'rb').read()
        if set(data)<= {0} or set(data)<={ord('x')}:
            continue
        lines=data.split(b'\n')
        for i,l in enumerate(lines):
            if not pat.match(l):
                print(p, i, l[:80])
EOF

